FIGS = [
 dict(id='OI01', slug='zigabeno', name='Eutimio Zigabeno', dates='c. 1050–después de 1118', img=f'{IMG}/zigabeno.jpg', pos='50% 20%',
  role='Monje del monasterio de la Peribleptos, en Constantinopla. Por encargo del emperador Alejo I Comneno compuso la «Panoplia dogmática», un arsenal contra todas las herejías.',
  why='Su título 28, «Contra los sarracenos», es la refutación sistemática más antigua de este pack: llama a Mahoma «falso profeta» y reduce el Corán a «fabulillas».',
  foot='Citas: Panoplia dogmática, tít. 28 (PG 130, col. 1333–1342). Griego de Migne con el latín al lado, leído en la imagen de la página (transcripción mía). Traducción al español mía desde el griego; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«Entonces se alzó entre ellos un [[k:falso profeta]], Mahoma, [[k:grande y famoso por sus blasfemias]].»',
        work='Panoplia dogmática, título 28: «Contra los sarracenos»', date='c. 1100–1118 · griego', ref='Panoplia dogmatica, tít. XXVIII, §1; PG 130, col. 1333–1334',
        trans='Griego de Migne, Patrologia Graeca 130 (reimpresión de 1864), con el latín al lado', url='https://archive.org/details/operaquaereperi00canggoog',
        orig='τότε δὲ ψευδοπροφήτης αὐτοῖς ἀνέστη Μωάμεθ, ὁ ταῖς βλασφημίαις μέγας καὶ περιδόξος.',
        clar='Así presenta Zigabeno a Mahoma al abrir su refutación: un «falso profeta» famoso por sus «blasfemias». A continuación da unos datos de su vida (huérfano, criado de una viuda) que son tradición bizantina y que no cito.'),
   dict(theme=['Q'], es='«Este Mahoma, aunque ignorante y rústico, [[k:compuso ciento trece «fabulillas»]] y a cada una le puso un nombre digno de su incultura y de su necedad. Contar y refutar la impureza y la evidente tontería de todas ellas equivale a [[k:sacar el estiércol de Augías]], como hizo Heracles. Dejando, pues, lo demás, recordaremos unas pocas cosas, las más necesarias, para conocer la secta y para condenarla.»',
        work='Panoplia dogmática, título 28: «Contra los sarracenos»', date='c. 1100–1118 · griego', ref='Panoplia dogmatica, tít. XXVIII, §9; PG 130, col. 1341–1342',
        trans='Griego de Migne (PG 130, reimpresión de 1864), con el latín al lado', url='https://archive.org/details/operaquaereperi00canggoog',
        orig='Οὗτος ὁ Μωάμεθ, καίτοι ἀμαθὴς ὢν καὶ ἄγροικος, τρία καὶ δέκα καὶ ἑκατὸν συνεγράψατο μυθάρια, ἑκάστῳ τούτων ὄνομα ἐπιθεὶς ἄξιον τῆς ἀπαιδευσίας καὶ μωρολογίας αὐτοῦ. Ὧν ἁπάντων τὴν ἀκαθαρσίαν καὶ τὴν πρόδηλον φλυαρίαν τὸ καὶ διηγήσασθαι καὶ ἀνατρέψαι ἴσον ἐστὶ τῷ τὴν Αὐγείου κόπρον ἐκκομίσαι, κατὰ τὸν Ἡρακλέα.',
        clar='Zigabeno dice que el Corán son 113 «fabulillas» (el Corán tiene 114 suras; el 113 es su cuenta) y que refutarlas todas sería como limpiar los establos de Augías. Por eso, dice, se limitará a las pocas más importantes.'),
   dict(theme=['Q'], es='«Y que Dios ignore si Cristo enseñó a los hombres que él también es Dios, y que por eso le pregunte, y que Dios, al negarlo Cristo, acepte por el momento su defensa: ¿qué condena no merecería esto? ¿Cómo va a ser Dios, si ignora lo ocurrido? ¿Y cómo es que Cristo, que según el Evangelio se llamó a sí mismo la Verdad, [[k:mintió ante Dios]] negando la verdad, siendo además Dios, como ya se demostró?»',
        work='Panoplia dogmática, título 28: «Contra los sarracenos»', date='c. 1100–1118 · griego', ref='Panoplia dogmatica, tít. XXVIII, §7; PG 130, col. 1339–1340',
        trans='Griego de Migne (PG 130, reimpresión de 1864), con el latín al lado', url='https://archive.org/details/operaquaereperi00canggoog',
        clar='Zigabeno razona sobre el diálogo coránico en que Dios pregunta a Jesús si dijo a los hombres que lo adoraran (compárese Corán 5:116) y Jesús lo niega. Para él eso haría a Dios ignorante y a Cristo mentiroso; lo presenta como un absurdo. Resume el pasaje, no lo cita palabra por palabra.'),
  ]),
 dict(id='OI02', slug='cantacuzeno', name='Juan VI Cantacuzeno', dates='c. 1292–1383', img=f'{IMG}/cantacuzeno.jpg', pos='50% 20%',
  role='Emperador bizantino de 1347 a 1354; después monje con el nombre de Joasaf. Gran teólogo ortodoxo, defensor del hesicasmo.',
  why='Se le atribuyen cuatro Discursos y cuatro Apologías «contra Mahoma»; en ellos lo compara con el diablo y lo llama «hijo de perdición».',
  foot='Citas: Cuatro discursos contra Mahoma (Basilea, 1543: griego con el latín de Rudolf Gwalther). Traduzco del latín y lo cotejo con el griego de la página. La edición de 1543 los atribuye al emperador; Schaff (1910) escribe «o más bien un monje Meletio, antes musulmán», pero el prefacio latino de 1543 (que leí solo en el texto digitalizado) presenta a Meletio acudiendo al emperador, que escribe él mismo la respuesta. Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«En cuanto a Mahoma, no sé por qué causa dio su ley —o, por decir más verdad, su desorden—, [[k:si no es movido por su padre, el diablo]]. Pues no se apoya en ningún testimonio tomado de otra parte: ni del Antiguo Testamento y los profetas, ni del Nuevo y los apóstoles.»',
        work='Cuatro discursos contra Mahoma, discurso I', date='c. 1355–1370 · griego (fecha no verificada)', ref='Discurso I (p. 78 de la ed. de Basilea, 1543)',
        trans='Griego de la ed. de Basilea, 1543 (Brylinger), con el latín de R. Gwalther', url='https://archive.org/details/jbc.bj.uj.edu.pl.NDIGSTDR048133',
        clar='Cantacuceno dice que Mahoma no puede citar a ningún profeta ni apóstol que lo avale; por tanto, su ley solo puede venir «de su padre, el diablo» (cf. Jn 8,44).'),
   dict(theme=['M'], es='«Además, [[k:lo que inventó sobre su propio nombre]] —que desde la eternidad está escrito en lo alto, a la derecha del trono divino, y que Cristo anunció a los hijos de Israel: «Os anuncio que vendrá después de mí el apóstol de Dios; su nombre es Mahoma»—. Como tal escritura no se encuentra ni en el Antiguo ni en el Nuevo Testamento y es [[k:una mentira clarísima]], sus sucesores inventaron que algunos, movidos por la envidia, la habían borrado: los judíos del Antiguo Testamento y los cristianos del Evangelio.»',
        work='Cuatro discursos contra Mahoma, discurso I', date='c. 1355–1370 · griego (fecha no verificada)', ref='Discurso I (p. 79 de la ed. de Basilea, 1543)',
        trans='Griego de la ed. de Basilea, 1543, con el latín de R. Gwalther', url='https://archive.org/details/jbc.bj.uj.edu.pl.NDIGSTDR048133',
        clar='Cantacuceno rechaza la tesis musulmana de que Cristo anunció a Mahoma por su nombre (compárese Corán 61:6): dice que esa frase no está en ninguna Biblia y que la explicación de que judíos y cristianos la borraron es otra invención.'),
   dict(theme=['M'], es='«¿Quién, en efecto, es mayor que Mahoma, que, como él mismo dijo de sí, superó los cielos y todas las potestades angélicas, habló con Dios, se hizo intercesor y patrono de los ángeles caídos y hasta abogado de todo el mundo? [[k:El diablo es homicida, y Mahoma condenó a muerte a quienes no obedecían sus leyes.]]»',
        work='Cuatro discursos contra Mahoma, discurso IV', date='c. 1355–1370 · griego (fecha no verificada)', ref='Discurso IV (p. 107 de la ed. de Basilea, 1543)',
        trans='Griego de la ed. de Basilea, 1543, con el latín de R. Gwalther', url='https://archive.org/details/jbc.bj.uj.edu.pl.NDIGSTDR048133',
        clar='Es una comparación retórica con el diablo: los títulos que Mahoma se da en el Corán y la tradición (ascensión, intercesor, abogado del mundo) y su trato a quienes no lo obedecían. Es una acusación histórica del autor; no es una llamada a matar a nadie. Omito el insulto que sigue en la misma página.'),
  ]),
 dict(id='OI03', slug='palamas', name='San Gregorio Palamás', dates='1296–1359', img=f'{IMG}/palamas.jpg', pos='50% 20%',
  role='Arzobispo de Tesalónica y principal teólogo del hesicasmo; santo de la Iglesia Ortodoxa. Capturado por los turcos en 1354, estuvo cautivo cerca de un año.',
  why='En la carta que escribe desde el cautiverio a su Iglesia cuenta sus debates con sabios musulmanes sobre Mahoma, el Evangelio y las conquistas.',
  foot='Citas: Carta desde el cautiverio a su Iglesia (1354), pp. 17 y 19 del Νέος Ἑλληνομνήμων 16 (1922). Griego leído en el escaneo de la edición (Olympias, Univ. de Ioánina, CC BY 4.0). Traducción al español mía desde el griego; no hay traducción inglesa de dominio público que haya leído. Fechas aproximadas.',
  quotes=[
   dict(theme=['M'], es='«Por eso nosotros creemos en Cristo y en su Evangelio; en cambio a Mahoma ni lo hallamos atestiguado por los profetas, ni [hallamos] que hiciera nada extraordinario y digno de nota que lleve a la fe: [[k:por eso no creemos en él, ni en el libro que dejó]].»',
        work='Carta desde el cautiverio a su Iglesia', date='1354 · griego', ref='Carta a su Iglesia (Neos Hellenomnemon 16, 1922), p. 17',
        trans='Griego, ed. de K. I. Dyovouniotis (1922); escaneo de Olympias (CC BY 4.0)', url='https://olympias.lib.uoi.gr/jspui/handle/123456789/1865',
        orig='Διὰ ταῦτα τοίνυν ἡμεῖς πιστεύομεν τῷ Χριστῷ καὶ τῷ εὐαγγελίῳ αὐτοῦ, τὸν δὲ Μαχούμετ οὔτε παρὰ τῶν προφητῶν εὑρίσκομεν μαρτυρούμενον, οὔτε τι ξένον εἰργασμένον καὶ ἀξιόλογον πρὸς πίστιν ἐνάγον· διὰ τοῦτο οὐ πιστεύομεν αὐτῷ, οὐδὲ τῷ παρ’ αὐτοῦ βιβλίῳ.',
        clar='Palamás responde a Tasimanes, el sabio turco que lo interroga: el criterio de todo creyente es el testimonio, y Cristo lo tiene (los profetas y sus obras) y Mahoma no. Por eso él no cree ni en Mahoma ni en su libro.'),
   dict(theme=['S'], es='«Mahoma, partiendo del oriente, llegó victorioso hasta el ocaso del sol, pero [[k:con guerra, espada, saqueo, esclavización y matanzas]]; nada de eso procede del Dios bueno, sino más bien de la voluntad del homicida desde el principio. ¿Y no sometió también Alejandro todo el Oriente partiendo del occidente? Muchos otros, en distintas épocas, tras muchas campañas dominaron toda la tierra, pero ningún pueblo confió su alma a ninguno de ellos, como vosotros a Mahoma.»',
        work='Carta desde el cautiverio a su Iglesia', date='1354 · griego', ref='Carta a su Iglesia (Neos Hellenomnemon 16, 1922), p. 19',
        trans='Griego, ed. de K. I. Dyovouniotis (1922); escaneo de Olympias (CC BY 4.0)', url='https://olympias.lib.uoi.gr/jspui/handle/123456789/1865',
        orig='Ἐξ ἀνατολῆς δὲ κινήσας ὁ Μωάμεθ, μέχρι καὶ δύσεως ἡλίου διῆλθε νικῶν, ἀλλὰ πολέμῳ καὶ μαχαίρᾳ καὶ λεηλασίᾳ καὶ ἀνδραποδισμοῖς καὶ ἀνδροκτασίαις· ὧν οὐδὲν ἐκ θεοῦ τοῦ ἀγαθοῦ προηγουμένως ἐστί, τοῦ ἐξ ἀρχῆς ἀνθρωποκτόνον δὲ μᾶλλον προηγούμενον θέλημα.',
        clar='Palamás contesta a Tasimanes, que presentaba las conquistas de Mahoma como prueba de su misión: las victorias, dice, no prueban la verdad (Alejandro también venció) y estas se hicieron con violencia. «Homicida desde el principio» es la expresión de Jn 8,44 para el diablo. Es un juicio teológico, no una llamada a nada.'),
   dict(theme=['H'], es='«Y sin embargo este hombre, [[k:aplicando la violencia a la vez que ofreciendo placeres]], no se ganó ni una sola parte entera del mundo habitado; en cambio la enseñanza de Cristo, aunque aparta de casi todos los placeres de la vida, abarcó todos los confines de la tierra y se impone en medio de quienes le hacen la guerra, sin aplicar violencia alguna, [[k:venciendo más bien la violencia que se le opone]] en cada ocasión.»',
        work='Carta desde el cautiverio a su Iglesia', date='1354 · griego', ref='Carta a su Iglesia (Neos Hellenomnemon 16, 1922), p. 19',
        trans='Griego, ed. de K. I. Dyovouniotis (1922); escaneo de Olympias (CC BY 4.0)', url='https://olympias.lib.uoi.gr/jspui/handle/123456789/1865',
        orig='καίτοι οὗτος, ὁμοῦ τε βίαν ἐπάγων καὶ τὰ καθ’ ἡδονὴν προτεινόμενος, οὐδὲ μέρος ἓν ὅλον τῆς οἰκουμένης προσεταιρίσατο· ἡ δὲ τοῦ Χριστοῦ διδασκαλία, καίτοι τῶν τοῦ βίου σχεδὸν ἁπάντων ἡδέων ἀπάγουσα, πάντα τε περιέσχε τῆς οἰκουμένης τὰ πέρατα, καὶ μεταξὺ τῶν αὐτῇ πολεμούντων κρατεῖ, μηδεμίαν αὕτη βίαν ἐπάγουσα, νικῶσα δὲ μᾶλλον τὴν ἀντεπαγομένην βίαν ἑκάστοτε.',
        clar='Palamás contrapone los dos caminos: Mahoma, con fuerza y con placeres; Cristo, sin fuerza y renunciando a los placeres, y aun así su enseñanza llegó a todo el mundo. Es la continuación del pasaje anterior y la respuesta que da a Tasimanes.'),
  ]),
 dict(id='OI04', slug='manuel-ii', name='Manuel II Paleólogo', dates='1350–1425', img=f'{IMG}/manuel-ii.jpg', pos='50% 20%',
  role='Emperador bizantino de 1391 a 1425. En el invierno de 1391, mientras servía al sultán Bayaceto en Ankara, escribió 26 diálogos con un docto musulmán (el mudarris).',
  why='El Diálogo VII contiene la frase que citó Benedicto XVI en Ratisbona en 2006: «muéstrame qué trajo Mahoma de nuevo y solo hallarás cosas malas e inhumanas».',
  foot='Citas: Diálogo con un persa, Diálogo VII (c. 1391–1392). Traducción al español mía desde el inglés de Roger Pearse (2009), que se declara de dominio público: el griego del Diálogo VII no está en Migne y solo figura en ediciones con derechos (Trapp, Khoury, 1966), así que no puedo mostrarlo. Fechas aproximadas.',
  quotes=[
   dict(theme=['H'], es='«Prueba de ello: si se preguntara a todos los hombres cuál es la mejor de todas las leyes y cuál, por el contrario, la peor, cada uno afirmaría que la suya es la mejor, pero que [[k:la de Mahoma es la peor]].»',
        work='Diálogo con un persa, Diálogo VII', date='c. 1391–1392 · griego', ref='Diálogo VII, cap. 2(b) (numeración de la traducción de Pearse)',
        trans='Inglés de Roger Pearse, 2009 (se declara de dominio público); sin griego de dominio público', url='https://www.tertullian.org/fathers/manuel_paleologus_dialogue7_trans.htm',
        clar='Manuel II lo dice en el diálogo con el persa: argumenta que, preguntando a todos los pueblos, la ley de Mahoma saldría como la peor. Es un argumento retórico («consenso de todos los hombres»), no una prueba doctrinal.'),
   dict(theme=['M', 'S'], es='«Así que no hay nada nuevo ahí, sino lo mismo dicho otra vez; o mejor, descaradamente saqueado. Pues muéstrame qué instituyó Mahoma de nuevo: [[k:solo encontrarás cosas malas o inhumanas]], como cuando ordena, decretándolo, que la creencia que predicó se propague por la espada.»',
        work='Diálogo con un persa, Diálogo VII', date='c. 1391–1392 · griego', ref='Diálogo VII, cap. 2(c) (numeración de la traducción de Pearse)',
        trans='Inglés de Roger Pearse, 2009 (se declara de dominio público); sin griego de dominio público', url='https://www.tertullian.org/fathers/manuel_paleologus_dialogue7_trans.htm',
        clar='Es el pasaje que citó Benedicto XVI en Ratisbona (2006), con otra redacción en inglés. Manuel sostiene que lo esencial de la ley de Mahoma viene de Abrahán y de Moisés, y que lo único nuevo es malo o inhumano, como la orden de difundir la fe por la espada.'),
   dict(theme=['S'], es='«Además, la fe es fruto del corazón, no del cuerpo. Quien pretende llevar a alguien a la fe necesita lenguaje hábil y pensamiento correcto, [[k:no violencia ni amenazas]], ni instrumento alguno para herir o intimidar. Pues así como para forzar a una naturaleza irracional no se recurriría a la persuasión, del mismo modo para persuadir a un alma racional no hace falta recurrir a la fuerza, ni al látigo, ni a ninguna amenaza de muerte.»',
        work='Diálogo con un persa, Diálogo VII', date='c. 1391–1392 · griego', ref='Diálogo VII, cap. 3(c) (numeración de la traducción de Pearse)',
        trans='Inglés de Roger Pearse, 2009 (se declara de dominio público); sin griego de dominio público', url='https://www.tertullian.org/fathers/manuel_paleologus_dialogue7_trans.htm',
        clar='Es el argumento de Manuel contra la difusión por la fuerza: la fe se persuade con razones. Antes ha sostenido que Dios no se complace en la sangre, así que la orden de convertir por la espada no puede venir de Él.'),
  ]),
]
